INSERT INTO document_chunks (source_name, version, effective_date, section_title, content, customer_scope, authority_level, embedding) VALUES ('03_Cancellation_and_Service_Credit_SOP_v4.pdf', 'v4_SOP', '2026-06-15', '2. Failed-pickup service credits (Default Policy)', '2. Failed-pickup service credits:
Under the default policy, a customer is eligible for a service credit when the pickup is more than 2 hours past the end of the scheduled pickup window, the carrier is at fault, and there is no customer-caused issue.
