INSERT INTO document_chunks (source_name, version, effective_date, section_title, content, customer_scope, authority_level, embedding) VALUES ('04_Product_Operations_Guide_and_Known_Issues.pdf', 'v1_OPS_GUIDE', '2026-08-14', '3. Known Issue KI-211: SwiftShip pickup webhook delay', 'KI-211 - SwiftShip pickup webhook delay (Opened: 12 August 2026, Status: Monitoring).
