INSERT INTO document_chunks (source_name, version, effective_date, section_title, content, customer_scope, authority_level, embedding) VALUES ('05_Northstar_Logistics_Enterprise_Agreement.pdf', 'v1_ENTERPRISE_AGREEMENT', '2026-01-01', '1. Northstar Custom Support Terms (Overrides Standard Policy)', 'ParcelPilot - Northstar Logistics Enterprise Agreement (Account: ACCT-001, Customer: Northstar Logistics, Term: 1 Jan 2026 - 31 Dec 2026, Status: ACTIVE).
1. Support terms: For Northstar Logistics, the following first-response targets replace ParcelPilot''s standard support-policy targets:
