INSERT INTO document_chunks (source_name, version, effective_date, section_title, content, customer_scope, authority_level, embedding) VALUES ('06_LumenWorks_Service_Agreement.pdf', 'v1_SERVICE_AGREEMENT', '2026-03-01', '2. LumenWorks Custom Failed-Pickup Credits (Overrides SOP)', '3. Failed-pickup credits:
